// generated by scripts/voice_tight.py: the narration was re-voiced with almost no pauses (reference pacing). The
// picture timeline (story.ts, cast.ts, world.ts) is still authored in the old clock; WARP maps each line's old start
// to its new start, and every component evaluates the old timeline at oldFrame(newFrame). Pairs are [old s, new s].
export const WARP: [number, number][] = [[0.15, 0.12], [2.573, 2.55], [4.145, 4.014], [5.641, 5.432], [9.012, 8.763], [9.726, 9.498], [10.582, 10.279], [11.14, 10.933], [12.621, 12.453], [13.145, 13.026], [14.005, 13.891], [16.943, 16.847], [19.736, 19.342], [23.566, 23.133], [25.146, 24.73], [26.35, 25.978], [27.706, 27.132], [28.507, 27.96], [29.353, 28.78], [29.905, 29.346], [30.419, 29.872], [32.079, 31.179], [33.504, 32.604], [34.843, 33.962], [39.214, 38.056], [40.591, 39.339], [42.579, 41.003], [44.902, 43.362], [46.112, 44.566], [47.809, 46.307], [50.001, 48.251], [53.223, 51.347], [53.719, 51.8], [54.843, 52.819], [55.687, 53.658], [57.493, 55.511], [59.129, 57.17], [60.731, 58.543], [62.962, 60.59], [65.83333333333333, 63.067]];
export const NEW_TOTAL = 1892;
/** fractional old-timeline frame for a frame of the re-timed video */
export const oldFrame = (f: number) => {
  const t = f / 30;
  if (t <= WARP[0][1]) return (WARP[0][0] * t / Math.max(1e-6, WARP[0][1])) * 30;
  for (let i = 1; i < WARP.length; i++) if (t <= WARP[i][1]) {
    const [o0, n0] = WARP[i - 1], [o1, n1] = WARP[i];
    return (o0 + ((t - n0) * (o1 - o0)) / (n1 - n0)) * 30;
  }
  return WARP[WARP.length - 1][0] * 30;
};
